def add_table(doc, headers, rows):
    table=doc.add_table(rows=1,cols=len(headers)); table.style='Table Grid'; table.alignment=WD_TABLE_ALIGNMENT.CENTER
    for i,h in enumerate(headers):
        c=table.rows[0].cells[i]; c.text=h; c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
        shade=OxmlElement('w:shd'); shade.set(qn('w:fill'),'1F4E78'); c._tc.get_or_add_tcPr().append(shade)
        for run in c.paragraphs[0].runs: run.bold=True; run.font.color.rgb=RGBColor(255,255,255); run.font.size=Pt(9)
    for row in rows:
        cells=table.add_row().cells
        for i,value in enumerate(row):
            cells[i].text=str(value); cells[i].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            for p in cells[i].paragraphs:
                p.paragraph_format.space_after=Pt(1)
                for r in p.runs: r.font.size=Pt(9)
    return table

doc=Document(TEMPLATE)
body=doc._element.body
for child in list(body):
    if child.tag!=qn('w:sectPr'): body.remove(child)
sec=doc.sections[0]; sec.page_width=Inches(8.5); sec.page_height=Inches(11)
sec.left_margin=Inches(.85); sec.right_margin=Inches(.85); sec.top_margin=Inches(.7); sec.bottom_margin=Inches(.75)
normal=doc.styles['Normal']; normal.font.name='Calibri'; normal.font.size=Pt(10.5); normal.font.color.rgb=RGBColor(38,50,63); normal.paragraph_format.space_after=Pt(6); normal.paragraph_format.line_spacing=1.08
for name,size,color in [('Title',27,'000000'),('Subtitle',12,'54708F'),('Heading 1',16,'17365D'),('Heading 2',12,'1F4E78')]:
    style=doc.styles[name]; style.font.name='Calibri'; style.font.size=Pt(size); style.font.color.rgb=RGBColor.from_string(color); style.font.bold=name!='Subtitle'

def page(title, paras, table=None):
    doc.add_page_break(); doc.add_heading(title,1)
    for para in paras: doc.add_paragraph(para)
    if table: add_table(doc,*table)

p=doc.add_paragraph(); p.paragraph_format.space_before=Pt(85); p.alignment=WD_ALIGN_PARAGRAPH.CENTER
